import type { RawMesh, Vec3 } from '../types';

export { dog, cat, pig, horse, elephant, giraffe, buildAnimal, type AnimalSpec, type LegStep } from './animals';

/** Built-in shapes, generated by us (no third-party models). Sizes are in millimetres. */

export function cube(size: number): RawMesh {
  const h = size / 2;
  const positions: Vec3[] = [
    [-h, -h, -h], [h, -h, -h], [h, h, -h], [-h, h, -h],
    [-h, -h, h], [h, -h, h], [h, h, h], [-h, h, h],
  ];
  return {
    positions,
    faces: [
      [0, 3, 2, 1], [4, 5, 6, 7], [0, 1, 5, 4], [2, 3, 7, 6], [1, 2, 6, 5], [3, 0, 4, 7],
    ],
  };
}

export function box(width: number, depth: number, height: number): RawMesh {
  const m = cube(1);
  return { positions: m.positions.map(([x, y, z]): Vec3 => [x * width, y * depth, z * height]), faces: m.faces };
}

export function tetrahedron(edge: number): RawMesh {
  const a = edge / Math.sqrt(8);
  const positions: Vec3[] = [[a, a, a], [a, -a, -a], [-a, a, -a], [-a, -a, a]];
  return { positions, faces: [[0, 1, 2], [0, 3, 1], [0, 2, 3], [1, 3, 2]] };
}

export function octahedron(edge: number): RawMesh {
  const r = edge / Math.SQRT2;
  const positions: Vec3[] = [[r, 0, 0], [-r, 0, 0], [0, r, 0], [0, -r, 0], [0, 0, r], [0, 0, -r]];
  return {
    positions,
    faces: [[0, 2, 4], [2, 1, 4], [1, 3, 4], [3, 0, 4], [2, 0, 5], [1, 2, 5], [3, 1, 5], [0, 3, 5]],
  };
}

export function icosahedron(edge: number): RawMesh {
  const t = (1 + Math.sqrt(5)) / 2;
  const s = edge / 2;
  const raw: Vec3[] = [
    [-1, t, 0], [1, t, 0], [-1, -t, 0], [1, -t, 0],
    [0, -1, t], [0, 1, t], [0, -1, -t], [0, 1, -t],
    [t, 0, -1], [t, 0, 1], [-t, 0, -1], [-t, 0, 1],
  ];
  const positions = raw.map(([x, y, z]): Vec3 => [x * s, y * s, z * s]);
  return {
    positions,
    faces: [
      [0, 11, 5], [0, 5, 1], [0, 1, 7], [0, 7, 10], [0, 10, 11],
      [1, 5, 9], [5, 11, 4], [11, 10, 2], [10, 7, 6], [7, 1, 8],
      [3, 9, 4], [3, 4, 2], [3, 2, 6], [3, 6, 8], [3, 8, 9],
      [4, 9, 5], [2, 4, 11], [6, 2, 10], [8, 6, 7], [9, 8, 1],
    ],
  };
}

export function dodecahedron(edge: number): RawMesh {
  const phi = (1 + Math.sqrt(5)) / 2;
  const s = edge / (2 / phi);
  const raw: Vec3[] = [];
  for (const x of [-1, 1]) for (const y of [-1, 1]) for (const z of [-1, 1]) raw.push([x, y, z]);
  for (const a of [-1, 1]) for (const b of [-1, 1]) raw.push([0, a / phi, b * phi]);
  for (const a of [-1, 1]) for (const b of [-1, 1]) raw.push([a / phi, b * phi, 0]);
  for (const a of [-1, 1]) for (const b of [-1, 1]) raw.push([a * phi, 0, b / phi]);
  const positions = raw.map(([x, y, z]): Vec3 => [x * s, y * s, z * s]);
  // Faces are found from the geometry: groups of five corners lying on one of the twelve face planes.
  const faces: number[][] = [];
  const dirs: Vec3[] = [];
  for (const a of [-1, 1]) for (const b of [-1, 1]) {
    dirs.push([a, 0, b * phi], [0, a * phi, b], [a * phi, b, 0]);
  }
  for (const d of dirs) {
    const len = Math.hypot(d[0], d[1], d[2]);
    const n: Vec3 = [d[0] / len, d[1] / len, d[2] / len];
    const dots = positions.map((p) => p[0] * n[0] + p[1] * n[1] + p[2] * n[2]);
    const top = Math.max(...dots);
    const ids = dots.map((v, i) => ({ v, i })).filter((e) => Math.abs(e.v - top) < 1e-6 * edge).map((e) => e.i);
    // Order the five corners around the normal.
    let cx = 0;
    let cy = 0;
    let cz = 0;
    for (const i of ids) {
      cx += positions[i][0] / ids.length;
      cy += positions[i][1] / ids.length;
      cz += positions[i][2] / ids.length;
    }
    const c: Vec3 = [cx, cy, cz];
    const ref = Math.abs(n[0]) < 0.9 ? ([1, 0, 0] as Vec3) : ([0, 1, 0] as Vec3);
    const u: Vec3 = [n[1] * ref[2] - n[2] * ref[1], n[2] * ref[0] - n[0] * ref[2], n[0] * ref[1] - n[1] * ref[0]];
    const ul = Math.hypot(u[0], u[1], u[2]);
    const uu: Vec3 = [u[0] / ul, u[1] / ul, u[2] / ul];
    const w: Vec3 = [n[1] * uu[2] - n[2] * uu[1], n[2] * uu[0] - n[0] * uu[2], n[0] * uu[1] - n[1] * uu[0]];
    ids.sort((p, q) => {
      const ang = (i: number) => {
        const d2: Vec3 = [positions[i][0] - c[0], positions[i][1] - c[1], positions[i][2] - c[2]];
        return Math.atan2(d2[0] * w[0] + d2[1] * w[1] + d2[2] * w[2], d2[0] * uu[0] + d2[1] * uu[1] + d2[2] * uu[2]);
      };
      return ang(p) - ang(q);
    });
    faces.push(ids);
  }
  return { positions, faces };
}

/** A prism with a regular n-gon base. */
export function prism(sides: number, radius: number, height: number): RawMesh {
  const positions: Vec3[] = [];
  for (const z of [0, height]) {
    for (let i = 0; i < sides; i++) {
      const a = (2 * Math.PI * i) / sides;
      positions.push([radius * Math.cos(a), radius * Math.sin(a), z]);
    }
  }
  const faces: number[][] = [Array.from({ length: sides }, (_, i) => sides - 1 - i), Array.from({ length: sides }, (_, i) => sides + i)];
  for (let i = 0; i < sides; i++) faces.push([i, (i + 1) % sides, sides + ((i + 1) % sides), sides + i]);
  return { positions, faces };
}

/** A pyramid with a regular n-gon base. */
export function pyramid(sides: number, radius: number, height: number): RawMesh {
  const positions: Vec3[] = [];
  for (let i = 0; i < sides; i++) {
    const a = (2 * Math.PI * i) / sides;
    positions.push([radius * Math.cos(a), radius * Math.sin(a), 0]);
  }
  positions.push([0, 0, height]);
  const faces: number[][] = [Array.from({ length: sides }, (_, i) => sides - 1 - i)];
  for (let i = 0; i < sides; i++) faces.push([i, (i + 1) % sides, sides]);
  return { positions, faces };
}

/**
 * A solid of revolution: `profile` is a list of [radius, height] from the bottom to the top. Radius 0 at an end
 * closes it with a point, a positive radius closes it with a flat cap. Gives gems, vases and bottles.
 */
export function lathe(profile: readonly [number, number][], segments: number): RawMesh {
  const positions: Vec3[] = [];
  const rings: number[][] = [];
  const poles: (number | null)[] = [null, null];
  profile.forEach(([r, h], pi) => {
    if (r === 0 && (pi === 0 || pi === profile.length - 1)) {
      poles[pi === 0 ? 0 : 1] = positions.length;
      positions.push([0, 0, h]);
      rings.push([]);
    } else {
      const ring: number[] = [];
      for (let i = 0; i < segments; i++) {
        const a = (2 * Math.PI * i) / segments;
        ring.push(positions.length);
        positions.push([r * Math.cos(a), r * Math.sin(a), h]);
      }
      rings.push(ring);
    }
  });
  const faces: number[][] = [];
  for (let p = 0; p + 1 < profile.length; p++) {
    const lo = rings[p];
    const hi = rings[p + 1];
    for (let i = 0; i < segments; i++) {
      const j = (i + 1) % segments;
      if (lo.length === 0) faces.push([poles[0]!, hi[j], hi[i]]);
      else if (hi.length === 0) faces.push([lo[i], lo[j], poles[1]!]);
      else faces.push([lo[i], lo[j], hi[j], hi[i]]);
    }
  }
  if (poles[0] === null) faces.push([...rings[0]].reverse());
  if (poles[1] === null) faces.push([...rings[rings.length - 1]]);
  return { positions, faces };
}

/** A low-poly gem: a pointed bottom, a wide middle and a flat top (table). */
export function gem(radius: number, segments = 8): RawMesh {
  return lathe([[0, 0], [radius * 0.98, radius * 0.9], [radius * 0.55, radius * 1.35]], segments);
}

/** A non-convex block: an L-shaped prism (tests concave edges and non-convex faces). */
export function lBlock(size: number): RawMesh {
  const u = size / 2;
  const outline: [number, number][] = [[0, 0], [2 * u, 0], [2 * u, u], [u, u], [u, 2 * u], [0, 2 * u]];
  const n = outline.length;
  const positions: Vec3[] = [...outline.map(([x, y]): Vec3 => [x, y, 0]), ...outline.map(([x, y]): Vec3 => [x, y, u])];
  const faces: number[][] = [Array.from({ length: n }, (_, i) => n - 1 - i), Array.from({ length: n }, (_, i) => n + i)];
  for (let i = 0; i < n; i++) faces.push([i, (i + 1) % n, n + ((i + 1) % n), n + i]);
  return { positions, faces };
}

/** A prism: `outline` (counter-clockwise or not) in the x-y plane, extruded up to `depth` in z. */
export function extrude(outlineIn: readonly [number, number][], depth: number): RawMesh {
  // Counter-clockwise, so the top faces up and the bottom faces down.
  let area = 0;
  outlineIn.forEach((p, i) => {
    const q = outlineIn[(i + 1) % outlineIn.length];
    area += p[0] * q[1] - q[0] * p[1];
  });
  const outline = area < 0 ? [...outlineIn].reverse() : outlineIn;
  const n = outline.length;
  const positions: Vec3[] = [...outline.map(([x, y]): Vec3 => [x, y, 0]), ...outline.map(([x, y]): Vec3 => [x, y, depth])];
  const faces: number[][] = [Array.from({ length: n }, (_, i) => n - 1 - i), Array.from({ length: n }, (_, i) => n + i)];
  for (let i = 0; i < n; i++) faces.push([i, (i + 1) % n, n + ((i + 1) % n), n + i]);
  return { positions, faces };
}

/** Turns a mesh a quarter turn so that what was z (up) is y: an outline in x-y becomes a front view in x-z. */
function standUp(mesh: RawMesh): RawMesh {
  // Swapping two axes mirrors the mesh, so the faces are turned over to keep them facing outward.
  return { positions: mesh.positions.map(([x, y, z]): Vec3 => [x, z, y]), faces: mesh.faces.map((f) => [...f].reverse()) };
}

export interface SweepSection {
  /** Where the section is, in the front view (x forward, z up); the sections run along a line or curve in the x-z plane. */
  x: number;
  z: number;
  /** Half width (sideways) and half height of the section; both 0 at an end makes a point. */
  width: number;
  height: number;
  /** Stretch the top / bottom corner of the section (a fin, a crest); 1 is none. Needs a multiple of 4 sides. */
  top?: number;
  bottom?: number;
}

/**
 * A body swept along a curve in the x-z plane: a ring of `sides` corners at every section, standing across the curve. Gives
 * fish, birds, bottles. Both ends are a point (width and height 0) or a flat cap.
 */
export function sweep(sections: readonly SweepSection[], sides = 8): RawMesh {
  const positions: Vec3[] = [];
  const rings: number[][] = [];
  const m = sections.length;
  sections.forEach((s, k) => {
    if (s.width === 0 && s.height === 0 && (k === 0 || k === m - 1)) {
      rings.push([positions.length]);
      positions.push([s.x, 0, s.z]);
      return;
    }
    const a = sections[Math.max(0, k - 1)];
    const b = sections[Math.min(m - 1, k + 1)];
    const tx = b.x - a.x;
    const tz = b.z - a.z;
    const len = Math.hypot(tx, tz) || 1;
    // The tangent and the "up" across it (the sideways direction is always y).
    const ux = tx / len;
    const uz = tz / len;
    const vx = -uz;
    const vz = ux;
    const ring: number[] = [];
    for (let i = 0; i < sides; i++) {
      const angle = (2 * Math.PI * i) / sides;
      const sin = Math.sin(angle);
      const boost = sin > 0.99 ? s.top ?? 1 : sin < -0.99 ? s.bottom ?? 1 : 1;
      const h = s.height * sin * boost;
      ring.push(positions.length);
      positions.push([s.x + vx * h, s.width * Math.cos(angle), s.z + vz * h]);
    }
    rings.push(ring);
  });
  const faces: number[][] = [];
  for (let p = 0; p + 1 < m; p++) {
    const lo = rings[p];
    const hi = rings[p + 1];
    for (let i = 0; i < sides; i++) {
      const j = (i + 1) % sides;
      if (lo.length === 1) faces.push([lo[0], hi[j], hi[i]]);
      else if (hi.length === 1) faces.push([lo[i], lo[j], hi[0]]);
      else {
        // Two triangles: the four corners are not always flat. Neighbours that turn out flat are merged again when the mesh is cleaned.
        faces.push([lo[i], lo[j], hi[j]], [lo[i], hi[j], hi[i]]);
      }
    }
  }
  if (rings[0].length > 1) faces.push([...rings[0]].reverse());
  if (rings[m - 1].length > 1) faces.push([...rings[m - 1]]);
  return { positions, faces };
}

/** A heart, a point at the bottom and a notch at the top, `size` wide, as an outline. */
export function heartOutline(size: number, points = 16): [number, number][] {
  const out: [number, number][] = [];
  for (let i = 0; i < points; i++) {
    const t = (2 * Math.PI * i) / points;
    const x = 16 * Math.sin(t) ** 3;
    const y = 13 * Math.cos(t) - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t);
    out.push([(x * size) / 32, (y * size) / 32]);
  }
  return out;
}

export function starOutline(radius: number, points = 5): [number, number][] {
  const out: [number, number][] = [];
  for (let i = 0; i < points * 2; i++) {
    const r = i % 2 === 0 ? radius : radius * 0.45;
    const a = Math.PI / 2 + (Math.PI * i) / points;
    out.push([r * Math.cos(a), r * Math.sin(a)]);
  }
  return out;
}

export const vase = (): RawMesh => lathe([[22, 0], [34, 18], [40, 40], [28, 70], [16, 90], [14, 100], [22, 116]], 8);
export const bottle = (): RawMesh => lathe([[30, 0], [30, 68], [22, 88], [13, 102], [13, 134]], 8);
export const lantern = (): RawMesh => lathe([[24, 0], [34, 20], [34, 70], [24, 90], [12, 100]], 6);
export const egg = (): RawMesh => lathe([[0, 0], [18, 8], [27, 26], [30, 48], [24, 72], [12, 90], [0, 98]], 8);
export const rocket = (): RawMesh => lathe([[14, 0], [16, 70], [10, 90], [0, 106]], 8);
export const house = (): RawMesh => standUp(extrude([[0, 0], [40, 0], [40, 30], [20, 48], [0, 30]], 40));
export const heartBox = (): RawMesh => extrude(heartOutline(60, 14), 25);
export const starBox = (): RawMesh => extrude(starOutline(40), 20);

export const fish = (): RawMesh =>
  sweep(
    [
      { x: -44, z: 0, width: 2, height: 14 },
      { x: -30, z: 0, width: 8, height: 11 },
      { x: -8, z: 0, width: 12, height: 20, top: 1.5, bottom: 1.1 },
      { x: 14, z: 0, width: 11, height: 18, top: 1.6, bottom: 1.1 },
      { x: 36, z: 0, width: 6, height: 9 },
      { x: 52, z: 0, width: 0, height: 0 },
    ],
    4,
  );

export const swan = (): RawMesh =>
  sweep(
    [
      { x: -52, z: 14, width: 0, height: 0 },
      { x: -40, z: 14, width: 8, height: 6 },
      { x: -18, z: 12, width: 22, height: 16 },
      { x: 6, z: 13, width: 24, height: 18 },
      { x: 24, z: 20, width: 15, height: 12 },
      { x: 31, z: 36, width: 8.5, height: 8.5 },
      { x: 34, z: 52, width: 7.5, height: 7.5 },
      { x: 35, z: 68, width: 7.5, height: 7.5 },
      { x: 35, z: 82, width: 7.5, height: 7.5 },
      { x: 40, z: 93, width: 7.5, height: 7 },
      { x: 52, z: 98, width: 0, height: 0 },
    ],
    5,
  );

export const BUILT_IN_SHAPES = {
  cube: (size = 50) => cube(size),
  tetrahedron: (size = 60) => tetrahedron(size),
  octahedron: (size = 50) => octahedron(size),
  icosahedron: (size = 40) => icosahedron(size),
  dodecahedron: (size = 30) => dodecahedron(size),
  gem: (size = 40) => gem(size),
  lBlock: (size = 60) => lBlock(size),
} as const;
